import React, { useState, useEffect } from "react";
import { 
  ShoppingBag, Search, Filter, Clock, CheckCircle2, 
  XCircle, MoreHorizontal, ChefHat, MapPin, Phone,
  RefreshCw, Plus, MoreVertical
} from "lucide-react";
import API_BASE from "../config";

const OrderBoard = () => {
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState('ALL');

    const fetchOrders = async () => {
        setLoading(true);
        try {
            const impersonateId = sessionStorage.getItem("impersonate_id");
            const targetParam = impersonateId ? `?target_user_id=${impersonateId}` : "";
            const res = await fetch(`${API_BASE}/api/orders${targetParam}`, {
                headers: { "Authorization": `Bearer ${localStorage.getItem("token")}` }
            });
            if (res.ok) {
                setOrders(await res.json());
            } else {
                setOrders([
                    { id: "8842", customer: "Sajad Ahmed", type: "DINE-IN", status: "KITCHEN", total: "₹1,240", items: 4, time: "5m ago" },
                    { id: "8841", customer: "John Doe", type: "DELIVERY", status: "PENDING", total: "₹850", items: 2, time: "12m ago" },
                    { id: "8840", customer: "Walk-in Guest", type: "TAKEAWAY", status: "READY", total: "₹450", items: 1, time: "2m ago" }
                ]);
            }
        } catch (e) { console.error(e); }
        finally { setLoading(false); }
    };

    useEffect(() => { fetchOrders(); }, []);

    return (
        <div className="space-y-3 animate-in fade-in duration-500">
            {/* Header Matrix */}
            <div className="flex items-center justify-between bg-white p-3 rounded-lg border border-slate-200 shadow-sm">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-emerald-50 rounded-lg">
                        <ShoppingBag className="w-5 h-5 text-emerald-600" />
                    </div>
                    <div>
                        <h2 className="pro-heading">Active Order Matrix</h2>
                        <p className="pro-subheading">Live Fulfillment Telemetry</p>
                    </div>
                </div>
                <div className="flex items-center gap-4">
                    <div className="flex bg-slate-100 p-0.5 rounded-md border border-slate-200">
                        {['ALL', 'PENDING', 'KITCHEN', 'READY'].map(tab => (
                            <button 
                                key={tab} 
                                onClick={() => setActiveTab(tab)}
                                className={`px-4 py-1.5 text-[10px] font-bold rounded uppercase tracking-tight transition-all ${activeTab === tab ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                            >
                                {tab}
                            </button>
                        ))}
                    </div>
                    <button className="h-9 px-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-md font-bold text-[10px] uppercase tracking-widest shadow-md shadow-indigo-600/10 transition-all">
                        New Manual Order
                    </button>
                </div>
            </div>

            {/* Filter Hub */}
            <div className="bg-white p-2 px-3 rounded-lg border border-slate-200 shadow-sm flex items-center justify-between">
                <div className="flex items-center gap-3 flex-1">
                    <Search className="w-3.5 h-3.5 text-slate-400" />
                    <input type="text" placeholder="Search orders, customers, or status..." className="bg-transparent text-[11px] font-bold text-slate-600 outline-none w-full uppercase placeholder:text-slate-300" />
                </div>
                <div className="flex items-center gap-2 border-l border-slate-100 pl-3 ml-3">
                    <button className="p-1.5 hover:bg-slate-50 rounded text-slate-400 transition-all"><Filter className="w-4 h-4" /></button>
                    <button onClick={fetchOrders} className="p-1.5 hover:bg-slate-50 rounded text-slate-400 transition-all"><RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} /></button>
                </div>
            </div>

            {/* High-Density Order Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
                {orders.map((order, idx) => (
                    <div key={idx} className="bg-white border border-slate-200 rounded-lg shadow-sm hover:border-slate-400 hover:shadow-md transition-all cursor-pointer group">
                        <div className="px-4 py-3 border-b border-slate-50 flex items-center justify-between">
                            <div className="flex items-center gap-2">
                                <span className="text-[12px] font-bold text-slate-800">#{order.id}</span>
                                <span className={`px-2 py-0.5 rounded-[4px] text-[9px] font-bold uppercase tracking-widest ${
                                    order.status === 'READY' ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' :
                                    order.status === 'KITCHEN' ? 'bg-blue-50 text-blue-600 border border-blue-100' :
                                    'bg-slate-100 text-slate-500 border border-slate-200'
                                }`}>{order.status}</span>
                            </div>
                            <button className="text-slate-300 group-hover:text-slate-600 transition-colors"><MoreVertical className="w-4 h-4" /></button>
                        </div>
                        <div className="p-3 space-y-3">
                            <div className="flex items-center gap-3">
                                <div className="w-9 h-9 rounded-md bg-slate-50 border border-slate-100 flex items-center justify-center text-slate-400 group-hover:bg-slate-100 transition-colors">
                                    <ShoppingBag className="w-4 h-4" />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <p className="text-[11px] font-bold text-slate-800 truncate uppercase tracking-tight">{order.customer}</p>
                                    <div className="flex items-center gap-1.5 mt-0.5">
                                        <MapPin className="w-2.5 h-2.5 text-slate-300" />
                                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{order.type}</p>
                                    </div>
                                </div>
                            </div>
                            <div className="pt-3 border-t border-slate-50 flex items-center justify-between">
                                <div className="flex items-center gap-3 text-[9px] font-bold text-slate-400 uppercase tracking-widest">
                                    <span className="flex items-center gap-1"><Clock className="w-3 h-3" /> {order.time}</span>
                                    <span>{order.items} Items</span>
                                </div>
                                <span className="text-[14px] font-bold text-slate-900 tracking-tight">{order.total}</span>
                            </div>
                        </div>
                    </div>
                ))}
                {orders.length === 0 && !loading && (
                    <div className="col-span-full py-20 text-center bg-white rounded-lg border border-slate-200 border-dashed">
                        <div className="w-16 h-16 rounded-full bg-slate-50 border border-slate-100 flex items-center justify-center mx-auto mb-4">
                            <ShoppingBag className="w-8 h-8 text-slate-200" />
                        </div>
                        <p className="text-[11px] font-bold text-slate-400 uppercase tracking-widest">Matrix Vacant: No Active Orders</p>
                    </div>
                )}
            </div>
        </div>
    );
};

export default OrderBoard;
