import React, { useState, useEffect } from "react";
import { Plus, Users, Trash2, Search, RefreshCw, Filter, Edit3, Shield, Mail, Phone, UserCircle, X, Check } from "lucide-react";
import API_BASE from "../config";

const OutletUserManager = () => {
    const [users, setUsers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [designations, setDesignations] = useState([]);
    const [formData, setFormData] = useState({
        username: "",
        password: "",
        name: "",
        phone: "",
        email: "",
        designation_id: "",
        user_type: "POS Billing",
        status: "active"
    });
    const [isEditing, setIsEditing] = useState(false);
    const [editId, setEditId] = useState(null);
    const [notification, setNotification] = useState(null); // Keep for errors
    const [showSuccess, setShowSuccess] = useState(false);
    const [confirmation, setConfirmation] = useState(null); // { title, message, onConfirm }

    const fetchDesignations = async () => {
        try {
            const impersonateId = sessionStorage.getItem("impersonate_id");
            let url = `${API_BASE}/api/brand/designations`;
            const params = new URLSearchParams();
            if (impersonateId) {
                params.append("target_user_id", impersonateId);
                params.append("outlet_id", impersonateId);
            }
            if (params.toString()) url += `?${params.toString()}`;

            const res = await fetch(url, {
                headers: { "Authorization": `Bearer ${localStorage.getItem("token")}` }
            });
            const data = await res.json();
            setDesignations(Array.isArray(data) ? data : []);
        } catch (e) { console.error(e); }
    };

    const fetchUsers = async () => {
        try {
            const impersonateId = sessionStorage.getItem("impersonate_id");
            const targetParam = impersonateId ? `?target_user_id=${impersonateId}` : "";
            const res = await fetch(`${API_BASE}/api/brand/users${targetParam}`, {
                headers: { "Authorization": `Bearer ${localStorage.getItem("token")}` }
            });
            const data = await res.json();
            setUsers(Array.isArray(data) ? data : []);
        } catch (e) { console.error(e); }
        finally { setLoading(false); }
    };

    useEffect(() => { 
        fetchUsers(); 
        fetchDesignations();
    }, []);
    
    useEffect(() => {
        if (showSuccess) {
            const timer = setTimeout(() => setShowSuccess(false), 2000);
            return () => clearTimeout(timer);
        }
    }, [showSuccess]);

    const handleDelete = (id) => {
        setConfirmation({
            title: "Delete Personnel Identity",
            message: "Are you sure you want to permanently delete this identity? This action will remove the user and all associated logs immediately.",
            onConfirm: async () => {
                try {
                    const res = await fetch(`${API_BASE}/api/brand/users/${id}`, {
                        method: "DELETE",
                        headers: { "Authorization": `Bearer ${localStorage.getItem("token")}` }
                    });
                    if (res.ok) {
                        setShowSuccess(true);
                        fetchUsers();
                    } else {
                        const errorData = await res.json();
                        setNotification({ type: "error", message: `Deletion Failed: ${errorData.error}` });
                    }
                } catch (e) { 
                    setNotification({ type: "error", message: "Network Error: Failed to reach security gateway." });
                }
                setConfirmation(null);
            }
        });
    };

    const handleEdit = (user) => {
        setFormData({
            username: user.username || "",
            password: "",
            name: user.name || "",
            phone: user.phone || "",
            email: user.email || "",
            designation_id: user.designation_id || "",
            user_type: user.user_type || "POS Billing",
            status: user.status || "active"
        });
        setEditId(user.id);
        setIsEditing(true);
        setIsModalOpen(true);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const impersonateId = sessionStorage.getItem("impersonate_id");
            const url = isEditing ? `${API_BASE}/api/brand/users/${editId}` : `${API_BASE}/api/brand/users`;
            const method = isEditing ? "PUT" : "POST";

            const res = await fetch(url, {
                method: method,
                headers: { 
                    "Content-Type": "application/json",
                    "Authorization": `Bearer ${localStorage.getItem("token")}`
                },
                // Force web_access to false for outlet-managed users
                body: JSON.stringify({ ...formData, web_access: false, target_user_id: impersonateId })
            });
            if (res.ok) {
                setShowSuccess(true);
                setIsModalOpen(false);
                setIsEditing(false);
                setEditId(null);
                setFormData({ username: "", password: "", name: "", phone: "", email: "", designation_id: "", user_type: "POS Billing", status: "active" });
                fetchUsers();
            } else {
                const errorData = await res.json();
                setNotification({ type: "error", message: `Operation Failed: ${errorData.error}` });
            }
        } catch (err) { 
            setNotification({ type: "error", message: "Network Error: Failed to reach orchestration server." });
        }
    };

    return (
        <div className="space-y-4 animate-in fade-in duration-500">
            <div className="flex items-center justify-between bg-white dark:bg-[#1e2129] p-3 rounded-lg border border-slate-200 dark:border-white/5 shadow-sm">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-emerald-50 dark:bg-emerald-500/10 rounded-lg">
                        <Users className="w-5 h-5 text-emerald-600" />
                    </div>
                    <div>
                        <h2 className="pro-heading">Manage Users</h2>
                        <p className="pro-subheading">Manage staff and login credentials</p>
                    </div>
                </div>
                <div className="flex items-center gap-2">
                    <button onClick={fetchUsers} className="h-9 px-4 bg-white dark:bg-white/5 hover:bg-slate-50 dark:hover:bg-white/10 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-white/5 rounded-md text-[10px] font-bold uppercase tracking-widest transition-all flex items-center gap-2">
                        <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} /> Sync
                    </button>
                    <button 
                        onClick={() => {
                            setIsEditing(false);
                            setEditId(null);
                            setFormData({ username: "", password: "", name: "", phone: "", email: "", designation_id: "", user_type: "POS Billing", status: "active" });
                            setIsModalOpen(true);
                        }}
                        className="h-9 px-4 bg-emerald-600 hover:bg-emerald-500 text-white rounded-md font-bold text-[10px] uppercase tracking-widest transition-all flex items-center gap-2 shadow-md shadow-emerald-600/10"
                    >
                        <Plus className="w-3.5 h-3.5" /> Add User
                    </button>
                </div>
            </div>

            <div className="bg-white dark:bg-[#1e2129] p-3 rounded-lg border border-slate-200 dark:border-white/5 flex items-center justify-between shadow-sm">
                <div className="flex items-center gap-3 flex-1">
                    <Search className="w-4 h-4 text-slate-400" />
                    <input type="text" placeholder="Filter personnel by name or identity..." className="bg-transparent text-[11px] font-bold text-slate-600 dark:text-slate-300 outline-none w-full uppercase placeholder:text-slate-300 dark:placeholder:text-slate-600" />
                </div>
                <button className="p-2 hover:bg-slate-50 dark:hover:bg-white/5 rounded-md text-slate-400 transition-all"><Filter className="w-4 h-4" /></button>
            </div>

            {loading ? (
                <div className="bg-white dark:bg-[#1e2129] rounded-lg border border-slate-200 dark:border-white/5 py-32 text-center shadow-sm">
                    <div className="flex flex-col items-center gap-4">
                        <div className="w-12 h-12 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin" />
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.3em]">Scanning Credential Vaults...</p>
                    </div>
                </div>
            ) : (
                <div className="bg-white dark:bg-[#1e2129] rounded-lg border border-slate-200 dark:border-white/5 overflow-hidden shadow-sm">
                    <table className="pro-table">
                        <thead>
                            <tr>
                                <th>Action</th>
                                <th>#</th>
                                <th>Name Identity</th>
                                <th>Operational Node</th>
                                <th>Communication</th>
                                <th>Authentication ID</th>
                                <th>Security Code</th>
                                <th>Role Protocol</th>
                                <th>Node Context</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100 dark:divide-white/5">
                            {users.map((u, idx) => (
                                <tr key={u.id} className="hover:bg-slate-50 dark:hover:bg-white/[0.02] transition-colors group">
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-1.5 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button onClick={() => handleEdit(u)} className="p-1.5 bg-slate-100 dark:bg-white/5 hover:bg-indigo-600 hover:text-white rounded text-slate-400 transition-all border border-slate-200 dark:border-white/10 shadow-sm active:scale-90"><Edit3 className="w-3.5 h-3.5" /></button>
                                            <button onClick={() => setConfirmation({
                                                title: "Security Reset",
                                                message: `Generate new access credentials for ${u.name}?`,
                                                onConfirm: () => { /* Password reset logic */ }
                                            })} className="p-1.5 bg-slate-100 dark:bg-white/5 hover:bg-emerald-600 hover:text-white rounded text-slate-400 transition-all border border-slate-200 dark:border-white/10 shadow-sm active:scale-90"><Shield className="w-3.5 h-3.5" /></button>
                                            <button onClick={() => handleDelete(u.id)} className="p-1.5 bg-slate-100 dark:bg-white/5 hover:bg-rose-600 hover:text-white rounded text-slate-400 transition-all border border-slate-200 dark:border-white/10 shadow-sm active:scale-90"><Trash2 className="w-3.5 h-3.5" /></button>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-[11px] font-bold text-slate-400">{idx + 1}</td>
                                    <td className="px-6 py-4">
                                        <span className="text-[12px] font-bold text-slate-800 dark:text-slate-200 uppercase tracking-tight">{u.name}</span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-tight">{u.outlet_name || 'Global Cluster'}</span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className="text-[11px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-tight">{u.phone || 'N/A'}</span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className="text-[11px] font-bold text-indigo-500 dark:text-indigo-400 uppercase tracking-tight">{u.username}</span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className="text-[12px] font-black text-emerald-500 dark:text-emerald-400 tracking-[0.2em]">{u.access_code || '---'}</span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className="text-[11px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-tight">{u.designation_name || 'Unassigned'}</span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className="px-2 py-0.5 rounded bg-slate-100 dark:bg-white/5 text-slate-500 dark:text-slate-400 text-[9px] font-bold uppercase border border-slate-200 dark:border-white/5">
                                            {u.user_type}
                                        </span>
                                    </td>
                                </tr>
                            ))}
                            {users.length === 0 && (
                                <tr>
                                <td colSpan="9" className="py-32 text-center">
                                        <div className="flex flex-col items-center gap-4 opacity-20">
                                            <div className="w-20 h-20 rounded-full border-2 border-dashed border-slate-300 dark:border-white/10 flex items-center justify-center">
                                                <UserCircle className="w-10 h-10 text-slate-400" />
                                            </div>
                                            <div>
                                                <p className="text-[12px] font-bold text-slate-500 uppercase tracking-widest">Registry Vacant</p>
                                                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mt-1">No Personnel Credentials provisioned</p>
                                            </div>
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            )}
            {/* Provision Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
                    <form onSubmit={handleSubmit} className="bg-white dark:bg-[#1e2129] w-full max-w-2xl rounded-xl border border-slate-200 dark:border-white/10 shadow-2xl overflow-hidden">
                        <div className="p-4 bg-slate-50 dark:bg-black/20 border-b border-slate-200 dark:border-white/5 flex items-center justify-between">
                            <h3 className="text-[12px] font-bold text-slate-800 dark:text-white uppercase tracking-widest">{isEditing ? 'Update User' : 'Add User'}</h3>
                            <button type="button" onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 dark:hover:text-white"><X className="w-5 h-5" /></button>
                        </div>
                        
                        <div className="p-6 grid grid-cols-2 gap-4">
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Login Username</label>
                                <input required value={formData.username} onChange={e => setFormData({...formData, username: e.target.value})} className="w-full bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-lg px-4 py-2.5 text-slate-900 dark:text-white outline-none focus:border-emerald-500 transition-all font-bold text-[12px]" placeholder="unique_id" />
                            </div>
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{isEditing ? 'New Password (Optional)' : 'Security Password'}</label>
                                <input required={!isEditing} type="password" value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} className="w-full bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-lg px-4 py-2.5 text-slate-900 dark:text-white outline-none focus:border-emerald-500 transition-all font-bold text-[12px]" placeholder="••••••••" />
                            </div>
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Personnel Name</label>
                                <input required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-lg px-4 py-2.5 text-slate-900 dark:text-white outline-none focus:border-emerald-500 transition-all font-bold text-[12px]" placeholder="Full Name" />
                            </div>
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Primary Phone</label>
                                <input required value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-lg px-4 py-2.5 text-slate-900 dark:text-white outline-none focus:border-emerald-500 transition-all font-bold text-[12px]" placeholder="+91 ..." />
                            </div>
                            <div className="space-y-1.5 col-span-2">
                                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Email Address</label>
                                <input type="email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-lg px-4 py-2.5 text-slate-900 dark:text-white outline-none focus:border-emerald-500 transition-all font-bold text-[12px]" placeholder="personnel@brand.com" />
                            </div>
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Role Type</label>
                                <select required value={formData.user_type} onChange={e => setFormData({...formData, user_type: e.target.value})} className="w-full bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-lg px-4 py-2.5 text-slate-900 dark:text-white outline-none font-bold text-[12px]">
                                    <option value="POS Billing">POS Billing</option>
                                    <option value="OrderHub">OrderHub (Captain/KDS)</option>
                                    <option value="Delivery Boy">Delivery Boy</option>
                                    <option value="Waiter">Waiter</option>
                                </select>
                            </div>
                            <div className="space-y-1.5">
                                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Designation Identity</label>
                                <select required value={formData.designation_id} onChange={e => setFormData({...formData, designation_id: e.target.value})} className="w-full bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-lg px-4 py-2.5 text-slate-900 dark:text-white outline-none font-bold text-[12px]">
                                    <option value="">-- Select Saved Designation --</option>
                                    {designations.map(d => (
                                        <option key={d.id} value={d.id}>{d.name}</option>
                                    ))}
                                </select>
                            </div>
                            <div className="space-y-4 pt-2">
                                <label className="flex items-center justify-between p-4 bg-slate-50 dark:bg-black/20 border border-slate-200 dark:border-white/10 rounded-xl cursor-pointer hover:bg-slate-100 dark:hover:bg-white/5 transition-all group">
                                    <div className="flex flex-col">
                                        <span className="text-[11px] font-bold text-slate-700 dark:text-slate-200 uppercase tracking-wide">Operational Status</span>
                                        <span className="text-[9px] text-slate-400 font-medium uppercase tracking-wider">{formData.status === 'active' ? 'Account Active (POS Access Granted)' : 'Account Suspended (All Access Revoked)'}</span>
                                    </div>
                                    <div className="relative inline-flex items-center">
                                        <input 
                                            type="checkbox" 
                                            checked={formData.status === 'active'} 
                                            onChange={e => setFormData({...formData, status: e.target.checked ? 'active' : 'inactive'})} 
                                            className="sr-only peer" 
                                        />
                                        <div className="w-11 h-6 bg-slate-300 dark:bg-white/10 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-emerald-500 shadow-inner"></div>
                                    </div>
                                </label>
                            </div>
                        </div>

                        <div className="p-4 bg-slate-50 dark:bg-black/20 border-t border-slate-200 dark:border-white/5 flex gap-3">
                            <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-2 text-[11px] font-bold text-slate-400 hover:text-slate-600 dark:hover:text-white uppercase tracking-widest">Cancel</button>
                            <button type="submit" className="flex-[2] py-2 bg-emerald-600 hover:bg-emerald-500 text-white rounded text-[11px] font-bold uppercase tracking-widest shadow-lg shadow-emerald-600/20">{isEditing ? 'Update' : 'Create'}</button>
                        </div>
                    </form>
                </div>
            )}

            {/* Success Dialogue - Centered & Auto-dismiss */}
            {showSuccess && (
                <div className="fixed inset-0 z-[2000] flex items-center justify-center p-6 bg-slate-900/40 backdrop-blur-sm animate-in fade-in duration-300">
                    <div className="bg-white dark:bg-[#1e2129] w-full max-w-xs rounded-xl border border-slate-200 dark:border-white/10 shadow-2xl overflow-hidden p-10 text-center animate-in zoom-in duration-300">
                        <div className="w-20 h-20 bg-emerald-500/10 text-emerald-500 rounded-full flex items-center justify-center mx-auto mb-6 shadow-inner ring-8 ring-emerald-500/5">
                            <Check className="w-12 h-12" />
                        </div>
                        <h4 className="text-[20px] font-black text-slate-800 dark:text-white uppercase tracking-tight mb-2">Success !</h4>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.15em]">Registry Updated Successfully</p>
                    </div>
                </div>
            )}

            {/* Error Notification Dialogue */}
            {notification && notification.type === 'error' && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/40 backdrop-blur-[2px] animate-in fade-in duration-300">
                    <div className="bg-white dark:bg-[#1e2129] w-full max-w-sm rounded-xl border border-slate-200 dark:border-white/10 shadow-2xl overflow-hidden p-6 text-center animate-in zoom-in-95 duration-200">
                        <div className="w-16 h-16 rounded-full mx-auto mb-4 flex items-center justify-center bg-rose-100 text-rose-600">
                            <X className="w-8 h-8" />
                        </div>
                        <h4 className="text-[14px] font-bold text-slate-800 dark:text-white uppercase tracking-tight mb-2">Attention</h4>
                        <p className="text-[11px] font-medium text-slate-500 dark:text-slate-400 mb-6 uppercase tracking-wide leading-relaxed">{notification.message}</p>
                        <button 
                            onClick={() => setNotification(null)}
                            className="w-full py-2.5 bg-slate-900 dark:bg-white/10 hover:bg-slate-800 dark:hover:bg-white/20 text-white dark:text-white rounded-lg text-[10px] font-bold uppercase tracking-[0.2em] transition-all"
                        >
                            Acknowledge
                        </button>
                    </div>
                </div>
            )}

            {/* Custom Confirmation Dialogue */}
            {confirmation && (
                <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/40 backdrop-blur-[2px] animate-in fade-in duration-300">
                    <div className="bg-white dark:bg-[#1e2129] w-full max-w-md rounded-xl border border-slate-200 dark:border-white/10 shadow-2xl overflow-hidden p-6 animate-in zoom-in-95 duration-200">
                        <div className="flex items-start gap-4 mb-6">
                            <div className="p-3 bg-rose-50 dark:bg-rose-500/10 rounded-lg text-rose-600">
                                <Trash2 className="w-6 h-6" />
                            </div>
                            <div>
                                <h4 className="text-[14px] font-bold text-slate-800 dark:text-white uppercase tracking-tight">{confirmation.title}</h4>
                                <p className="text-[11px] font-medium text-slate-500 dark:text-slate-400 mt-1 uppercase tracking-wide leading-relaxed">{confirmation.message}</p>
                            </div>
                        </div>
                        <div className="flex gap-3">
                            <button onClick={() => setConfirmation(null)} className="flex-1 py-2.5 bg-slate-50 dark:bg-white/5 hover:bg-slate-100 dark:hover:bg-white/10 text-slate-600 dark:text-slate-400 rounded-lg text-[10px] font-bold uppercase tracking-[0.2em] transition-all">Abort</button>
                            <button onClick={confirmation.onConfirm} className="flex-1 py-2.5 bg-rose-600 hover:bg-rose-500 text-white rounded-lg text-[10px] font-bold uppercase tracking-[0.2em] transition-all shadow-lg shadow-rose-600/20">Confirm Deletion</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};


export default OutletUserManager;
